#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode {
    pub val: i32,
    pub next: Option<Box<ListNode>>,
}

impl ListNode {
    #[inline]
    pub fn new(val: i32) -> Self {
        ListNode { next: None, val }
    }
}

pub struct Solution;

impl Solution {
    pub fn merge_two_lists(
        list1: Option<Box<ListNode>>,
        list2: Option<Box<ListNode>>,
    ) -> Option<Box<ListNode>> {
        let mut l1 = list1;
        let mut l2 = list2;
        let mut dummy = ListNode::new(0);
        let mut tail = &mut dummy;

        while l1.is_some() && l2.is_some() {
            let take_l1 = l1.as_ref().unwrap().val <= l2.as_ref().unwrap().val;
            if take_l1 {
                let next = l1.as_mut().unwrap().next.take();
                tail.next = l1;
                tail = tail.next.as_mut().unwrap();
                l1 = next;
            } else {
                let next = l2.as_mut().unwrap().next.take();
                tail.next = l2;
                tail = tail.next.as_mut().unwrap();
                l2 = next;
            }
        }

        tail.next = if l1.is_some() { l1 } else { l2 };

        dummy.next
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn to_list(vals: &[i32]) -> Option<Box<ListNode>> {
        let mut head = None;
        for &v in vals.iter().rev() {
            let mut node = Box::new(ListNode::new(v));
            node.next = head;
            head = Some(node);
        }
        head
    }

    fn to_vec(mut list: Option<Box<ListNode>>) -> Vec<i32> {
        let mut res = Vec::new();
        while let Some(node) = list {
            res.push(node.val);
            list = node.next;
        }
        res
    }

    #[test]
    fn test_example1() {
        let l1 = to_list(&[1, 2, 4]);
        let l2 = to_list(&[1, 3, 4]);
        let merged = Solution::merge_two_lists(l1, l2);
        assert_eq!(to_vec(merged), vec![1, 1, 2, 3, 4, 4]);
    }

    #[test]
    fn test_both_empty() {
        let l1 = to_list(&[]);
        let l2 = to_list(&[]);
        let merged = Solution::merge_two_lists(l1, l2);
        assert_eq!(to_vec(merged), vec![]);
    }

    #[test]
    fn test_one_empty() {
        let l1 = to_list(&[]);
        let l2 = to_list(&[0]);
        let merged = Solution::merge_two_lists(l1, l2);
        assert_eq!(to_vec(merged), vec![0]);
    }

    #[test]
    fn test_different_lengths() {
        let l1 = to_list(&[2, 5, 7, 9]);
        let l2 = to_list(&[1, 3]);
        let merged = Solution::merge_two_lists(l1, l2);
        assert_eq!(to_vec(merged), vec![1, 2, 3, 5, 7, 9]);
    }
}
